import{_ as n,o,c as s,ag as d,j as r}from"./chunks/framework.KxDd3USm.js";const x=JSON.parse('{"title":"08.1 安全目标与密码技术 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"08-信息安全/01-安全目标与密码技术.md","filePath":"08-信息安全/01-安全目标与密码技术.md"}'),g={name:"08-信息安全/01-安全目标与密码技术.md"},a={class:"fig"},e={"data-figure-id":"figure-23",viewBox:"0 0 680 180",width:"100%",style:{"max-width":"680px"},role:"img","aria-label":"数字信封流程。A 用一次性对称密钥 K 加密正文，用 B 的公钥加密 K；B 用自己的私钥解开 K，再用 K 解密正文。对称加密负责大量正文，非对称加密只保护小的会话密钥。"};function h(u,t,l,i,q,_){return o(),s("div",null,[t[2]||(t[2]=d('<h1 id="_08-1-安全目标与密码技术-★★★" tabindex="-1">08.1 安全目标与密码技术 ★★★ <a class="header-anchor" href="#_08-1-安全目标与密码技术-★★★" aria-label="Permalink to &quot;08.1 安全目标与密码技术 ★★★&quot;">​</a></h1><p><strong>动机</strong>：先想清楚&quot;安全&quot;到底要保住什么，后面每个技术（加密、签名、防火墙）才能对号入座——<strong>每个安全技术都是为了守住某一条安全属性而生的</strong>。</p><h3 id="_1-1-五大安全属性" tabindex="-1">1.1 五大安全属性 <a class="header-anchor" href="#_1-1-五大安全属性" aria-label="Permalink to &quot;1.1 五大安全属性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>含义</th><th>一句话理解</th><th>被谁破坏</th></tr></thead><tbody><tr><td><strong>机密性</strong></td><td>信息不泄露给未授权者</td><td>偷看不得</td><td>截获/窃听</td></tr><tr><td><strong>完整性</strong></td><td>信息不被未授权篡改</td><td>改动不得</td><td>篡改</td></tr><tr><td><strong>可用性</strong></td><td>授权用户要用时能用</td><td>想用就能用</td><td>中断（如 DoS）</td></tr><tr><td><strong>不可否认性</strong></td><td>发过的话不能赖账</td><td>赖账不得</td><td>伪造/抵赖</td></tr><tr><td><strong>可控性</strong></td><td>对信息传播与内容具有控制能力</td><td>流传范围可控</td><td>越权传播</td></tr></tbody></table><p>选择题最爱的配对：<strong>截获→机密性；篡改→完整性；中断→可用性；伪造→真实性/不可否认性</strong>。记法：&quot;看（截获）改（篡改）断（中断）造（伪造）&quot;对&quot;密完可用真&quot;。</p><h3 id="_1-2-主动攻击-vs-被动攻击-★★★" tabindex="-1">1.2 主动攻击 vs 被动攻击 ★★★ <a class="header-anchor" href="#_1-2-主动攻击-vs-被动攻击-★★★" aria-label="Permalink to &quot;1.2 主动攻击 vs 被动攻击 ★★★&quot;">​</a></h3><p>这是历年真题反复考的二分类，判别标准只有一条：<strong>是否修改/破坏了系统中的数据和资源</strong>。</p><table tabindex="0"><thead><tr><th>类别</th><th>特征</th><th>包含的攻击</th></tr></thead><tbody><tr><td><strong>被动攻击</strong></td><td>只<strong>偷看</strong>，不改数据，难察觉</td><td><strong>窃听</strong>（网络监听、搭线）、<strong>流量分析</strong>（不看内容只分析通信的模式、频率、流向）</td></tr><tr><td><strong>主动攻击</strong></td><td><strong>动手改</strong>数据或破坏系统</td><td><strong>篡改</strong>、<strong>伪造</strong>、<strong>伪装</strong>（冒充他人）、<strong>重放</strong>、<strong>拒绝服务 DoS / 分布式拒绝服务 DDoS</strong></td></tr></tbody></table><p><strong>反例演示</strong>（最容易错的一道）：「流量分析」听起来很&quot;主动&quot;（在主动分析嘛），但它<strong>只观察通信模式、不修改任何数据</strong>，属于<strong>被动攻击</strong>。真题就爱把它混进&quot;主动攻击&quot;选项里。反向陷阱：「拒绝服务」听起来只是&quot;让服务慢一点&quot;，但它<strong>主动发起请求洪流破坏可用性</strong>，属于主动攻击。</p><p><strong>应试动作</strong>：背判断句&quot;<strong>只看不改是被动（窃听、流量分析），又改又砸是主动（篡改、伪造、伪装、重放、DoS/DDoS）</strong>&quot;。考场上题干给攻击名让你分类，或给&quot;以下不属于主动攻击的是&quot;——找&quot;窃听/流量分析&quot;。</p><h3 id="_1-3-贯穿总表-「属性-→-用什么技术-→-被什么攻击」-学完全课回来自检" tabindex="-1">1.3 贯穿总表：「属性 → 用什么技术 → 被什么攻击」（学完全课回来自检） <a class="header-anchor" href="#_1-3-贯穿总表-「属性-→-用什么技术-→-被什么攻击」-学完全课回来自检" aria-label="Permalink to &quot;1.3 贯穿总表：「属性 → 用什么技术 → 被什么攻击」（学完全课回来自检）&quot;">​</a></h3><p>把本课所有技术按&quot;它到底守住哪个属性&quot;串成一张表，做题时对号入座：</p><table tabindex="0"><thead><tr><th>安全属性</th><th>用哪种技术守住</th><th>被哪种攻击破坏</th></tr></thead><tbody><tr><td><strong>机密性</strong></td><td>加密（对称/非对称）、数字信封</td><td>窃听、流量分析（被动）</td></tr><tr><td><strong>完整性</strong></td><td>信息摘要（Hash）比对、数字签名</td><td>篡改</td></tr><tr><td><strong>可用性</strong></td><td>冗余、限流、CDN、防火墙</td><td>DoS/DDoS、资源耗尽攻击（海量请求蹭连接）</td></tr><tr><td><strong>不可否认性 / 真实性</strong></td><td>数字签名、数字证书（CA 认证身份）</td><td>伪造、伪装、抵赖</td></tr><tr><td><strong>可控性</strong></td><td>访问控制、操作审计</td><td>越权传播</td></tr></tbody></table><p>一句话穿起来：<strong>&quot;加密管机密、摘要管完整、签名管真实不赖账、防火墙/限流管可用、访问控制管可控&quot;</strong>——几乎每一章都是一个技术守一个属性、防一类攻击。考试时先问&quot;这题在考哪个属性&quot;，再反推用哪个技术/是哪类攻击。</p><hr><h2 id="第二节-对称加密与非对称加密-★★★" tabindex="-1">第二节 对称加密与非对称加密 ★★★ <a class="header-anchor" href="#第二节-对称加密与非对称加密-★★★" aria-label="Permalink to &quot;第二节 对称加密与非对称加密 ★★★&quot;">​</a></h2><p><strong>动机</strong>：想把一段话保密，最直观的办法是&quot;加密&quot;——用一把钥匙把明文搅成乱码，收到的人用钥匙再搅回来。那钥匙怎么设计？历史上只有&quot;同一把钥匙加又解&quot;，直到 1976 年才有人发明&quot;加解各用一把、成对出现&quot;的方案。这两条技术路线就是本节主角。</p><h3 id="_2-1-对比表-选择题直接查这张表作答" tabindex="-1">2.1 对比表（选择题直接查这张表作答） <a class="header-anchor" href="#_2-1-对比表-选择题直接查这张表作答" aria-label="Permalink to &quot;2.1 对比表（选择题直接查这张表作答）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>对称加密（私钥加密/共享密钥加密）</th><th>非对称加密（公钥加密/公开密钥加密）</th></tr></thead><tbody><tr><td>密钥结构</td><td>加密、解密用<strong>同一把</strong>密钥</td><td><strong>成对</strong>出现：公钥 + 私钥</td></tr><tr><td>密钥分发</td><td>难：必须先走秘密信道把钥匙送到对方手里</td><td>易：公钥可公开随便发，私钥自己藏着</td></tr><tr><td>n 人需要密钥数</td><td><strong>n(n−1)/2</strong> 个（每两人共用一把）</td><td><strong>2n</strong> 个（每人一对）</td></tr><tr><td>速度</td><td><strong>快</strong>（约快 1～2 个数量级）</td><td><strong>慢</strong></td></tr><tr><td>加密数据量</td><td>适合<strong>大量数据</strong></td><td>适合<strong>少量数据</strong>（密钥、摘要）</td></tr><tr><td>代表算法</td><td><strong>DES</strong>（分组 64 位，有效密钥 56 位）、3DES、<strong>AES</strong>（分组 128 位，密钥 128/192/256 位）、IDEA、RC-5</td><td><strong>RSA</strong>（基于大整数分解难题）、ECC（椭圆曲线）、ElGamal</td></tr><tr><td>能否数字签名／提供不可否认性</td><td><strong>原则上不能</strong>：加解密用同一把钥匙，发送方、接收方<strong>双方都有</strong>，&quot;签&quot;得出来却举证不了是谁签的</td><td><strong>能</strong>：<strong>私钥唯一</strong>，只有本人能签 → 提供不可否认性</td></tr></tbody></table><p><strong>记忆口诀</strong>：对称&quot;一把钥匙开一把锁，双方同款&quot;；非对称&quot;公锁私钥一对凑，公钥上锁私钥开&quot;。算法名归类口诀：<strong>&quot;DES、AES 是兄弟（对称），RSA 单干是公私（非对称）&quot;</strong>——考场上认名字：带 DES/AES/IDEA 的选对称，带 RSA/ECC/DSA 的选非对称。</p><p><strong>密钥数公式的来历</strong>（防遗忘就地展开）：n 个人两两通信都要保密，任何两人的密钥都不能与第三者相同，所以是&quot;从 n 人里取 2 人配一把&quot;= C(n,2) = n(n−1)/2。例如 n=10：C(10,2) = (10×9)/(2×1) = <strong>45</strong> 把。非对称则每人只需自己的一对：n=10 → 10 对共 20 把。这个对比正说明了非对称在密钥管理上的优势。</p><h3 id="_2-2-两个方向-别拧反了-本课第一易错点" tabindex="-1">2.2 两个方向，别拧反了（本课第一易错点） <a class="header-anchor" href="#_2-2-两个方向-别拧反了-本课第一易错点" aria-label="Permalink to &quot;2.2 两个方向，别拧反了（本课第一易错点）&quot;">​</a></h3><p>非对称加密的两把钥匙有<strong>两种用法</strong>，方向必须刻进脑子：</p><table tabindex="0"><thead><tr><th>用法</th><th>加密用谁</th><th>解密用谁</th><th>达到什么目的</th></tr></thead><tbody><tr><td><strong>加密（保密）</strong></td><td><strong>接收者的公钥</strong></td><td><strong>接收者的私钥</strong></td><td>只有收方能看 → 机密性</td></tr><tr><td><strong>签名（认证）</strong></td><td><strong>发送者的私钥</strong></td><td><strong>发送者的公钥</strong></td><td>只有本人能签 → 身份真实 + 不可否认</td></tr></tbody></table><p><strong>反例演示</strong>：「甲用乙的公钥加密后发给乙」✓ 保密方向；若写成「甲用自己的公钥加密后发给乙」就错了——公钥人人都有，别人也能解开，毫无保密性。「甲用乙的私钥签名」更是无中生有——乙的私钥只有乙自己有，甲根本拿不到；签名必须用自己的私钥。</p><p>一句话锁死：<strong>&quot;想让对方独看，用对方公钥锁；想证明是自己，用自己私钥签&quot;</strong>。</p><p><strong>为什么对称加密做不了数字签名（本节关键一问）</strong>：签名要提供&quot;不可否认性&quot;——证明&quot;这件事只有你能做、别人替不了&quot;。对称加密里加密和解密是<strong>同一把钥匙</strong>，收发双方都握着它，那么甲乙两人谁都能用这把钥匙做出&quot;签名效果&quot;，事后谁也说不清到底是甲还是乙签的——<strong>举证不了、无法定责</strong>，相当于&quot;章谁都能盖&quot;。数字签名必须依赖<strong>私钥唯一</strong>的非对称体系：全天下只有甲持有甲的私钥，甲签出来的东西别人仿造不出，才&quot;赖不掉&quot;。理解这一句，就等于掌握了&quot;数字签名为什么注定走非对称&quot;的根本原因——考题若问&quot;为什么对称加密不能提供不可否认性&quot;，答<strong>密钥双方共有、无法归因到唯一签名者</strong>。</p><h3 id="_2-3-数字信封-混合加密-★★★" tabindex="-1">2.3 数字信封（混合加密）★★★ <a class="header-anchor" href="#_2-3-数字信封-混合加密-★★★" aria-label="Permalink to &quot;2.3 数字信封（混合加密）★★★&quot;">​</a></h3><p><strong>动机</strong>：实战里&quot;鱼与熊掌要兼得&quot;——对称快但钥匙难送，非对称好送但慢。办法：<strong>用对称加密保护大数据，用对方的公钥只加密那把对称密钥</strong>。这个&quot;套了一层非对称外皮的对称密钥&quot;就叫<strong>数字信封</strong>。</p><p>流程（以 A 发给 B）：</p><ol><li>A 生成一把<strong>一次性对称密钥</strong> K，用 K 加密正文（快，管大数据）；</li><li>A 用 <strong>B 的公钥</strong>加密 K（只加密一小段，慢也无所谓）——这就是&quot;信封&quot;；</li><li>把密文 + 加了密的 K 一起发给 B；</li><li>B 用<strong>自己的私钥</strong>解出 K，再用 K 解开正文。</li></ol><p><strong>应试动作</strong>：背&quot;<strong>对称保正文，公钥保钥匙；封谁用谁公钥，拆封谁用谁私钥</strong>&quot;。选择题给出流程步骤让你填&quot;用谁的什么钥&quot;，按这句作答。DES/AES/RSA 名字归类题则直接查 2.1 对比表。</p>',32)),r("figure",a,[(o(),s("svg",e,[...t[0]||(t[0]=[d('<defs><marker id="env" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><rect x="35" y="50" width="120" height="42" rx="8" class="b"></rect><text x="60" y="76" class="t">正文 —K→ 密文</text><rect x="35" y="112" width="120" height="42" rx="8" class="b"></rect><text x="50" y="138" class="t">K —B 公钥→ 密钥密文</text><path d="M155 71H270M155 133H270" class="e" marker-end="url(#env)"></path><rect x="295" y="75" width="120" height="55" rx="8" fill="var(--gold-soft)" stroke="var(--gold)" stroke-width="2"></rect><text x="322" y="98" class="t">数字信封</text><text x="310" y="117" class="t">密文 + 加密 K</text><path d="M415 102H510" class="e" marker-end="url(#env)"></path><rect x="530" y="50" width="115" height="42" rx="8" class="b"></rect><text x="544" y="76" class="t">B 私钥解 K</text><rect x="530" y="112" width="115" height="42" rx="8" class="b"></rect><text x="542" y="138" class="t">K 解正文</text>',14)])])),t[1]||(t[1]=r("figcaption",null,"保密方向始终是“用接收者公钥封密钥、用接收者私钥拆密钥”。",-1))]),t[3]||(t[3]=r("hr",null,null,-1))])}const b=n(g,[["render",h]]);export{x as __pageData,b as default};
